TLM.f("Sancti/10-19",{"officium":"S. Petri de Alcantara Confessoris","rule":["vide C5;","Gloria"],"fallback":"Commune/C5","from":{"GradualeP":"Commune/C5","Tractus":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Ps 91:13-14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri."},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri."}],"Oratio":[{"k":"text","la":"Deus, qui beátum Petrum Confessórem tuum admirábilis pœniténtiæ et altíssimæ contemplatiónis múnere illustráre dignátus es: da nobis, quǽsumus; ut, ejus suffragántibus méritis, carne mortificáti, facílius cœléstia capiámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Philippénses"},{"k":"ref","la":"Philipp 3:7-12"},{"k":"text","la":"Fratres: Quæ mihi fuérunt lucra, hæc arbitrátus sum propter Christum defriménta. Verúmtamen exístimo ómnia detriméntum esse propter eminéntem sciéntiam Jesu Christi, Dómini mei: propter quem ómnia detriméntum feci et árbitror ut stércora, ut Christum lucrifáciam et invéniar in illo, non habens meam justítiam, quæ ex lege est, sed illam, quæ ex fide est Christi Jesu: quæ ex Deo est justítia in fide, ad cognoscéndum illum, et virtútem resurrectiónis ejus, et societátem passiónum illíus: configurátus morti ejus: si quo modo occúrram ad resurrectiónem, quæ est ex mórtuis: non quod jam accéperim aut jam perféctus sim: sequor autem, si quo modo comprehéndam, in quo et comprehénsus sum a Christo Jesu."}],"Graduale":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 111:1"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:32-34"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Nolíte timére, pusíllus grex, quia complácuit Patri vestro dare vobis regnum. Véndite quæ possidétis, et date eleemósynam. Fácite vobis sácculos, qui non veteráscunt, thesáurum non deficiéntem in cœlis: quo fur non apprópiat, neque tínea corrúmpit. Ubi enim thesáurus vester est, ibi et cor vestrum erit."}],"Offertorium":[{"k":"ref","la":"Ps 20:2-3"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus, et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Præsta nobis, quǽsumus, omnípotens Deus: ut nostræ humilitátis oblátio et pro tuórum tibi grata sit honóre Sanctórum, et nos córpore páriter et mente puríficet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 19:28-29"},{"k":"text","la":"Amen, dico vobis: quod vos, qui reliquístis ómnia et secúti estis me, céntuplum accipiétis, et vitam ætérnam possidébitis. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Quǽsumus, omnípotens Deus: ut, qui cœléstia aliménta percépimus, intercedénte beáto Petro Confessóre tuo, per hæc contra ómnia advérsa muniámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"6b4668e2db0b0991":{"t":"Ps 91, 13-14, Ps 91, 2\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik zasađen u Gospodnjem domu, u trijemovima hrama Boga našega. (Ps 91, 2) Dobro je slaviti Gospodina, i pjevati tvojemu imenu, Svevišnji.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik zasađen u Gospodnjem domu, u trijemovima hrama Boga našega.","kn":"(Ps. 91, 13-14). Pravednik cvate kao paoma i raste poput libanonskog cedra, usađen u domu Gospodnjem, u trijemovima hrama Boga našega. (Ps. 91, 2) Dobro je slaviti Gospodina i pjevati Imenu Tvomu, Višnji! Slava Ocu ... Pravednik .. .","knRef":"Kniewald 1942, str. 474–475 (snimka 238) (OCR)"},"39212fe6831bb6b9":{"t":"<i>Pomolimo se</i>.\nBože, koji si se udostojao blaženoga Petra priznavaoca svoga odlikovati darom izvanredne pokore i duhovnog promatranja, daj nam, molimo, da po njegovu zagovoru i zaslugama svladavamo tijelo i tako lakše shvatimo ono što je nebesko.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si se dostojao blaženoga Petra, priznavaoca svoga, proslaviti divnoin pokorom i darom najvišeg gledanja, podaj, molimo, da trapeći se u tijelu lakše shvatimo nebeske stvari, po G. n.","knRef":"Kniewald 1942, str. 742–743 (snimka 372) (OCR)"},"9fc5b33868e1626a":{"t":"Fil 3, 7-12\nČitanje Poslanice bl. Pavla apostola Filipljanima. Braćo, sve ono što mi je nešto vrijedilo držao sam radi Krista štetnim. Još više sve držim štetnim prema neusporedivom dobru spoznaje moga Gospodina Isusa Krista. Radi njega sam se odrekao svega i sve držim kao blato samo zato da steknem Krista i budem u njemu i to ne svojom pravednošću po zakonu, nego po vjeri Isusa Krista, pravednošću koja je po vjeri od Boga, da spoznam njega i moć njegova uskrsnuća, da budem dionik njegovih muka i postanem mu sličan u smrti, da na kakav način postignem uskrsnuće od mrtvih. Ovo ne kažem, kao da sam to već postigao, ili da sam već savršen. Ja i nadalje nastojim, da bih što dobio kao što je i mene pridobio Isus Krist.","kn":"Čitanje poslanice bi. Pavla apostola Filipljanima (3, 7-12). Braćo! Sto mi je bilo od koristi, to sam radi Krista držao gubitkom. Pače sve držim gubitkom po uzvišenoj spoznaji Isusa Krista, moga Go- r Sv. Marcelo 16. I. spodlna, radi kojega sam se odrekao svega i sve držim kao izmet zato, da stečem Krista i da se nađem u njemu: Ne po svojoj pravednosti iz zakona, nego po vjeri Isfusa Krista: po Piravednosti, koja je po vjeri od Boga, da spoznam njega i moć njegova uskrsnuća i zajednicu njegovih muka, da mu postanem sličan u smrti, da na koji način dođem do uskrsnuća od mrtvih. Ali ne kao da sam ja već postigao' ili da sam savršen. Nego revno nastojim, ne bih li kako obuhvatio, kako sam i ja bio obuhvaćen od Isusa Krista.","knRef":"Kniewald 1942, str. 474–475 (snimka 238) (OCR)"},"6d9e364d27075ba3":{"t":"Ps 36, 30-31\nPravednikova usta raspravljaju o mudrosti i njegov jezik govori o pravdi. Zakon mu je Božji u srcu, i noge mu neće posrnuti.\n\nPs 111, 1\n<i>aleluja</i>, <i>aleluja</i>.\nBlago čovjeku koji se boji Gospodina i koji uživa u njegovim zapovijedima. <i>Aleluja</i>.","kn":"(Ps. 36, 30-31). Pravednikova usta govore mudrost i njegov jezik kazuje pravdu. Zakon je Božji u njegovu srcu i njegove noge ne ce posrnuti.\n\nAleluja, aleluja. (Ps. 111, 1.) Blago čovjeku, koji se boji Go.spodma, .koji žudi zapovijedi njegove, aleluja.","knRef":"Kniewald 1942, str. 540–541 (snimka 271) (OCR)"},"1cac10fd63222759":{"t":"Lk 12, 32-34\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus svojim učenicima: Nemojte se bojati, malo stado, jer je vaš Otac odlučio dati vam kraljevstvo. Prodajte što imate i dajte milostinju. Načinite sebi torbe koje neće ostarjeti, neprolazno blago na nebu, kamo se ne približava lupež, niti izjeda moljac. Jer gdje je vaše blago, ondje će biti i vaše srce.","kn":"t Slijedi sv. evanđelje po Luki (12,32-34). U ono vrijeme reče Isus svojim učenicima: Nemojte se bojati, malo stado, jer je vaš Otac odlučio dati vam kraljevstvo. Prodajte, što imate i dajte milostinju. Načinite sebi kese, koje ne stare; neprolazno blago na nebu, kamo se ne približava tat niti izjeda moljac. Jer gdje je vaše blago, ondje će biti i vaše srce.","knRef":"Kniewald 1942, str. 818–819 (snimka 410) (OCR)"},"4e296f3326e0e479":{"t":"Ps 20, 2-3\nU jakosti tvojoj, Gospodine, raduje se pravednik i kliče radi tvoga spasenja, jer si mu ispunio želju srca njegova.","kn":"(Ps. 20, 2-'3). U kreposti Tvojoj Gospodine, raduje se pravednik i kliče nad spasenjem Tvojim, jer si mu ispunio želju duše njegove.","knRef":"Kniewald 1942, str. 818–819 (snimka 410) (OCR)"},"1e8de8be36cd864e":{"t":"Daj nam, molimo, svemogući Bože, da naš ponizni prinos bude tebi drag zbog časti tvojih svetih,i neka očisti naše tijelo i dušu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj nam, molimo, svemogući Bože, da prinos naše smjernostl bude i Tebi mio radi časti svetaca, i nas da očisti zajedno na tijelu i na duši. Po Gospodinu ...","knRef":"Kniewald 1942, str. 450–451 (snimka 226) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"d76f89b9ab1556d0":{"t":"Mt 19, 28 i 29\nZaista vam kažem da ćete vi koji ste ostavili sve i pošli za mnom primiti stostruko i baštiniti život vječni.","kn":"(Mt. 19, 28, 29). Zaista vam kažem, da čete vi, koji ste sve ostavili 1 koji ste pošli za mnom, primiti stoput onoliko i baštinit ćete život vječni.","knRef":"Kniewald 1942, str. 620–621 (snimka 311) (OCR)"},"7b33fe9d71178bc3":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, da nas nebeska hrana koju smo primili zagovorom blaženoga Petra, tvoga priznavaoca zaštiti od svih protivnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, svemo'gući Bože, da nas nebeska hrana, koju primismo, zagovorom blaženoga I., priznavaoca Tvoga, zaštiti od svih protivnosti. Po G. n.","knRef":"Kniewald 1942, str. 818–819 (snimka 410) (OCR)"}}});
